#!/usr/bin/env bash
# Generates a .env file with random secrets for docker compose.
# Usage: scripts/generate-env.sh [--force]
set -euo pipefail

cd "$(dirname "$0")/.."

if [[ -f .env && "${1:-}" != "--force" ]]; then
  echo ".env already exists. Re-run with --force to overwrite it." >&2
  exit 1
fi

# Alphanumeric only: Kafka SCRAM config and JDBC URLs do not need escaping then.
rand() {
  LC_ALL=C tr -dc 'A-Za-z0-9' </dev/urandom | head -c "${1:-32}"
}

cat > .env <<EOF
# Generated by scripts/generate-env.sh — do not commit.

# Public URL of the frontend; Keycloak is served under <url>/auth and uses it as token issuer.
FINGUARD_PUBLIC_URL=http://localhost:3000
# Keycloak refuses plain HTTP from non-private addresses unless this is "none".
# Local HTTP only; use "external" (the default) once the site is served over HTTPS.
KEYCLOAK_SSL_REQUIRED=none

# Keycloak admin console (master realm), only on http://127.0.0.1:8180/auth/admin
KEYCLOAK_ADMIN_PASSWORD=$(rand 24)
# Administrator of the finguard realm (application role ADMIN)
FINGUARD_ADMIN_EMAIL=admin@finguard.local
FINGUARD_ADMIN_PASSWORD=$(rand 20)

# PostgreSQL superuser and one role per service database
POSTGRES_PASSWORD=$(rand)
KEYCLOAK_DB_PASSWORD=$(rand)
TXN_DB_PASSWORD=$(rand)
FRAUD_DB_PASSWORD=$(rand)
NOTIFICATION_DB_PASSWORD=$(rand)
AUDIT_DB_PASSWORD=$(rand)

# Redis
REDIS_PASSWORD=$(rand)

# Kafka SCRAM users (one per service)
KAFKA_ADMIN_PASSWORD=$(rand)
KAFKA_TXN_PASSWORD=$(rand)
KAFKA_FRAUD_PASSWORD=$(rand)
KAFKA_NOTIFICATION_PASSWORD=$(rand)
KAFKA_AUDIT_PASSWORD=$(rand)
KAFKA_GATEWAY_PASSWORD=$(rand)
EOF

chmod 600 .env
echo "Wrote .env. App admin: admin@finguard.local / FINGUARD_ADMIN_PASSWORD; Keycloak console: admin / KEYCLOAK_ADMIN_PASSWORD."
